#include <string>
#include <vector>
#include <queue>

class Fenwick {
    int n;
    std::vector<int> tree;
public:
    Fenwick(int n) : n(n), tree(n + 1, 0) {}
    void add(int i, int delta) {
        for (++i; i <= n; i += i & -i) tree[i] += delta;
    }
    int query(int i) {
        int s = 0;
        for (++i; i > 0; i -= i & -i) s += tree[i];
        return s;
    }
};

class Solution {
public:
    std::string minInteger(std::string num, int k) {
        int n = num.size();
        std::vector<std::queue<int>> pos(10);
        for (int i = 0; i < n; ++i) pos[num[i] - '0'].push(i);
        Fenwick bit(n);
        std::string res = "";
        for (int i = 0; i < n; ++i) {
            for (int d = 0; d < 10; ++d) {
                if (!pos[d].empty()) {
                    int orig = pos[d].front();
                    int cost = orig - bit.query(orig);
                    if (cost <= k) {
                        k -= cost;
                        bit.add(orig, 1);
                        pos[d].pop();
                        res += std::to_string(d);
                        break;
                    }
                }
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    static class Fenwick {
        int n;
        int[] tree;
        Fenwick(int n) { this.n = n; tree = new int[n + 1]; }
        void add(int i, int delta) {
            for (++i; i <= n; i += i & -i) tree[i] += delta;
        }
        int query(int i) {
            int s = 0;
            for (++i; i > 0; i -= i & -i) s += tree[i];
            return s;
        }
    }
    public String minInteger(String num, int k) {
        int n = num.length();
        Queue<Integer>[] pos = new Queue[10];
        for (int i = 0; i < 10; i++) pos[i] = new ArrayDeque<>();
        for (int i = 0; i < n; i++) pos[num.charAt(i) - '0'].add(i);
        Fenwick bit = new Fenwick(n);
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int d = 0; d < 10; d++) {
                if (!pos[d].isEmpty()) {
                    int orig = pos[d].peek();
                    int cost = orig - bit.query(orig);
                    if (cost <= k) {
                        k -= cost;
                        bit.add(orig, 1);
                        pos[d].poll();
                        res.append(d);
                        break;
                    }
                }
            }
        }
        return res.toString();
    }
}

