var minInteger = function(num, k) {
    const n = num.length;
    const pos = Array.from({ length: 10 }, () => []);
    for (let i = 0; i < n; i++) pos[num.charCodeAt(i) - 48].push(i);
    const bit = new Fenwick(n);
    const res = [];
    for (let i = 0; i < n; i++) {
        for (let d = 0; d < 10; d++) {
            if (pos[d].length > 0) {
                const orig = pos[d][0];
                const cost = orig - bit.query(orig);
                if (cost <= k) {
                    k -= cost;
                    bit.add(orig, 1);
                    pos[d].shift();
                    res.push(d);
                    break;
                }
            }
        }
    }
    return res.join("");
